<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import { ArrowRight, X } from "lucide-vue-next";
import { useUiStore } from "../stores/ui";
import { useRepoStore } from "../stores/repo";
import Button from "../components/ui/button.vue";
import type { Input } from "../../../core/input.js";
import { relTime } from "../lib/time";
import Dialog from "../components/ui/dialog/root.vue";
import DialogClose from "../components/ui/dialog/close.vue";
import DialogContent from "../components/ui/dialog/content.vue";
import DialogDescription from "../components/ui/dialog/description.vue";
import DialogOverlay from "../components/ui/dialog/overlay.vue";
import DialogTitle from "../components/ui/dialog/title.vue";
import Select from "../components/ui/select/root.vue";
import SelectContent from "../components/ui/select/content.vue";
import SelectItem from "../components/ui/select/item.vue";
import SelectTrigger from "../components/ui/select/trigger.vue";
import SelectValue from "../components/ui/select/value.vue";
import SelectViewport from "../components/ui/select/viewport.vue";
import Checkbox from "../components/ui/checkbox.vue";
const ui = useUiStore(), repo = useRepoStore(), inputs = ref<Input[]>([]), activeInput = ref<Input | null>(null);
const statuses = [{ id: "new", label: "New", color: "#39e0ff" }, { id: "reviewing", label: "Reviewing", color: "#ffb454" }, { id: "processed", label: "Processed", color: "#4ef0a8" }];
const storageKey = "inputs-filter-selected";
const selected = ref(new Set(["new", "reviewing"]));
const visible = computed(() => inputs.value.filter((i) => selected.value.has(i.status)));
async function load(): Promise<void> { inputs.value = await repo.loadInputs(); }
function loadFiltersFromStorage(): void { try { const stored = localStorage.getItem(storageKey); selected.value = new Set(stored ? JSON.parse(stored) : ["new", "reviewing"]); } catch { selected.value = new Set(["new", "reviewing"]); } }
function saveFiltersToStorage(): void { try { localStorage.setItem(storageKey, JSON.stringify(Array.from(selected.value))); } catch { } }
function toggle(id: string): void { const next = new Set(selected.value); next.has(id) ? next.delete(id) : next.add(id); selected.value = next; saveFiltersToStorage(); }
async function move(i: Input, status: string): Promise<void> { i.status = status as Input["status"]; await repo.updateInput(i.id, status); }
function nextStatus(status: Input["status"]): Input["status"] | null { return status === "new" ? "reviewing" : status === "reviewing" ? "processed" : null; }
function moveNext(i: Input): void { const next = nextStatus(i.status); if (next) void move(i, next); }
function statusLabel(status: Input["status"]): string { return statuses.find((s) => s.id === status)?.label ?? status; }
function openInput(input: Input): void { activeInput.value = input; }
function onInputsUpdated(): void { void load(); }
onMounted(() => { loadFiltersFromStorage(); void load(); window.addEventListener("repoos:inputs-updated", onInputsUpdated); });
onBeforeUnmount(() => window.removeEventListener("repoos:inputs-updated", onInputsUpdated));
</script>
<template>
  <div class="inputs-page"><div class="inputs-header"><div><div class="page-title">Inputs</div><div class="page-desc">Ideas, questions, bugs, and feedback waiting to be shaped into work or knowledge.</div></div><Button variant="accent" class="new-btn" @click="ui.openNewInput"><span class="plus">+</span> New input</Button></div><div class="input-filters" role="group" aria-label="Filter inputs by status"><label v-for="s in statuses" :key="s.id" class="input-filter"><Checkbox :checked="selected.has(s.id)" @update:checked="toggle(s.id)" /><span class="status-dot" :style="{ background: s.color }"></span>{{ s.label }} <span class="filter-count">{{ inputs.filter(i => i.status === s.id).length }}</span></label></div><div v-if="!visible.length" class="inputs-empty"><div class="empty-title">No inputs here yet</div><div>Capture an idea, question, bug, or observation for the team.</div><Button variant="outline" @click="ui.openNewInput">Submit your first input</Button></div><div v-else class="input-list"><article v-for="i in visible" :key="i.id" class="input-row" tabindex="0" @click="openInput(i)" @keyup.enter="openInput(i)"><div class="input-row-main"><div class="input-row-meta"><span class="input-status" :class="i.status"><span class="state-dot"></span>{{ i.status }}</span><span v-if="i.type">{{ i.type }}</span><span v-if="i.area">{{ i.area }}</span><span>by {{ i.createdBy || 'Unknown' }}</span><span v-if="i.createdAt">{{ new Date(i.createdAt).toLocaleDateString() }}</span></div><h2>{{ i.title }}</h2><p>{{ i.body }}</p><div v-if="i.attachments.length" class="attachment-meta">{{ i.attachments.length }} attachment{{ i.attachments.length === 1 ? '' : 's' }}</div></div><Button v-if="nextStatus(i.status)" variant="outline" class="move-next" @click.stop="moveNext(i)"><ArrowRight class="size-3.5" /><span class="state-dot" :class="'state-' + nextStatus(i.status)"></span> Move to {{ nextStatus(i.status) }}</Button></article></div>
    <Dialog :open="!!activeInput" @update:open="(v) => { if (!v) activeInput = null }"><DialogOverlay /><DialogContent :style="{ width: ui.drawerWidth + 'px', 'max-width': '100vw' }"><div class="drawer-resize" @mousedown.prevent="ui.startResize"></div><div class="drawer-head"><DialogTitle>{{ activeInput?.title }}</DialogTitle><DialogDescription class="sr-only">Input details</DialogDescription><DialogClose class="close-x"><X class="size-[15px]" /></DialogClose></div><div v-if="activeInput" class="drawer-body input-detail"><div class="detail-status"><Select :model-value="activeInput.status" @update:model-value="(v) => move(activeInput!, v ?? '')"><SelectTrigger class="detail-select"><span class="select-label"><span class="state-dot" :class="'state-' + activeInput.status"></span>{{ statusLabel(activeInput.status) }}</span></SelectTrigger><SelectContent position="popper"><SelectViewport class="min-w-[var(--radix-select-trigger-width)]"><SelectItem v-for="s in statuses" :key="s.id" :value="s.id"><span class="state-dot" :class="'state-' + s.id"></span>{{ s.label }}</SelectItem></SelectViewport></SelectContent></Select><Button v-if="nextStatus(activeInput.status)" variant="outline" class="move-next" @click="moveNext(activeInput)"><ArrowRight class="size-3.5" /><span class="state-dot" :class="'state-' + nextStatus(activeInput.status)"></span> Move to {{ nextStatus(activeInput.status) }}</Button></div><div class="detail-meta"><span>{{ activeInput.type || 'other' }}</span><span>{{ activeInput.area || 'Unknown area' }}</span><span>Created by {{ activeInput.createdBy || 'Unknown' }}</span><span v-if="activeInput.createdAt">Created {{ relTime(activeInput.createdAt) }}</span></div><div class="detail-body">{{ activeInput.body }}</div><div v-if="activeInput.attachments.length" class="detail-attachments"><strong>Attachments</strong><div v-for="a in activeInput.attachments" :key="a.name" class="attachment-card"><img v-if="a.mime.startsWith('image/')" :src="`/api/inputs/${activeInput.id}/attachments/${encodeURIComponent(a.name)}`" :alt="a.name" /><a :href="`/api/inputs/${activeInput.id}/attachments/${encodeURIComponent(a.name)}`" target="_blank" rel="noreferrer">{{ a.name }}</a></div></div></div></DialogContent></Dialog>
  </div>
</template>
<style scoped>
.inputs-page { max-width:1000px; margin:0 auto; padding:28px 30px 80px; }.inputs-header { display:flex; align-items:flex-end; justify-content:space-between; margin-bottom:22px; gap:20px; }.input-filters { display:flex; flex-wrap:wrap; gap:9px; padding:12px; margin-bottom:16px; background:var(--panel); border:1px solid var(--border); border-radius:11px; }.input-filter { display:inline-flex; align-items:center; gap:7px; padding:7px 10px; border-radius:8px; color:var(--txt-secondary); font-size:12px; cursor:pointer; }.input-filter:hover { background:var(--nav-hover-bg); color:var(--txt); }.input-filter input { accent-color:var(--cyan); }.status-dot { width:8px; height:8px; border-radius:50%; }.filter-count { color:var(--txt-faint); font-family:var(--font-mono); }.input-list { display:flex; flex-direction:column; gap:9px; }.input-row { display:flex; justify-content:space-between; gap:22px; padding:17px 18px; background:var(--panel); border:1px solid var(--border); border-radius:11px; cursor:pointer; }.input-row:hover, .input-row:focus-visible { border-color:var(--border-focus); outline:none; }.input-row-main { min-width:0; }.input-row h2 { margin:7px 0 5px; font-size:15px; font-weight:600; color:var(--txt); }.input-row p { margin:0; white-space:pre-wrap; color:var(--txt-secondary); font-size:13px; line-height:1.5; }.input-row-meta, .detail-meta { display:flex; gap:10px; align-items:center; color:var(--txt-faint); font-size:11px; }.input-status { display:inline-flex; align-items:center; gap:6px; padding:3px 7px; border-radius:999px; text-transform:capitalize; background:var(--bg-secondary); }.state-dot { width:7px; height:7px; flex:0 0 auto; border-radius:50%; background:currentColor; }.state-new { color:var(--cyan); }.state-reviewing { color:#ffb454; }.state-processed { color:#4ef0a8; }.input-status.new { color:var(--cyan); }.input-status.reviewing { color:#ffb454; }.input-status.processed { color:#4ef0a8; }.status-select { align-self:flex-start; min-width:110px; padding:7px 8px; border:1px solid var(--border); border-radius:7px; background:var(--bg-secondary); color:var(--txt-secondary); font-size:12px; }.move-next { align-self:flex-start; white-space:nowrap; }.input-row > .move-next { margin-left:auto; }.attachment-meta { margin-top:9px; color:var(--txt-faint); font-size:11px; }.inputs-empty { display:flex; flex-direction:column; align-items:center; gap:12px; padding:80px 20px; color:var(--txt-faint); text-align:center; border:1px dashed var(--border); border-radius:12px; }.empty-title { color:var(--txt); font-size:15px; font-weight:600; }.plus { font-size:18px; line-height:12px; }.input-detail { display:flex; flex-direction:column; gap:12px; }.detail-status { display:flex; align-items:center; gap:10px; margin-top:-7px; }.detail-status .detail-select { min-width:120px; align-self:auto; }.detail-body { white-space:pre-wrap; color:var(--txt); font-size:14px; line-height:1.65; }.detail-attachments { display:flex; flex-direction:column; gap:9px; color:var(--txt-secondary); font-size:12px; }.attachment-card { display:flex; flex-direction:column; gap:5px; padding:8px; border:1px solid var(--border); border-radius:8px; }.attachment-card img { max-width:100%; max-height:260px; object-fit:contain; border-radius:5px; background:var(--bg-secondary); }.attachment-card a { color:var(--cyan); overflow-wrap:anywhere; }.detail-select { align-self:stretch; }
@media (max-width:650px) { .inputs-page { padding:20px 14px 70px; }.inputs-header { align-items:flex-start; flex-direction:column; }.input-row { flex-direction:column; gap:12px; }.status-select { align-self:stretch; } }
</style>
<style scoped>
/* Group the dot and label together on the left, chevron on the right. */
.detail-select .select-label { display: flex; align-items: center; gap: 6px; }
</style>
